const msg = $input.first().json.body?.message;
const photos = msg?.photo;
if (!photos || photos.length === 0) throw new Error('Sem foto');
// Pega a maior resolução
const foto = photos.reduce((a, b) => ((b.file_size ?? 0) > (a.file_size ?? 0) ? b : a));
return [{ json: { file_id: foto.file_id, chat_id: msg.chat.id, user_id: msg.from?.id, nome: msg.from?.first_name } }];

// Converte binário para base64
const binaryData = $binary.data;
const base64 = binaryData.toString('base64');
return [{ json: { ...($('Extrair Foto').item.json), base64_foto: base64 } }];

const resposta = $input.first().json;
const conteudo = JSON.parse(resposta.choices[0].message.content);
const chatId = $('Extrair Foto').item.json.chat_id;
return [{ json: { ...conteudo, chat_id: chatId } }];
